1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface ClaimStep {
23	  op: "claim";
24	  policy: number;
25	  incident: { cause: string; damages: Damage[] };
26	}
27	
28	export type Step = QuoteStep | ClaimStep;
29	
30	export interface Scenario {
31	  customer: Customer;
32	  steps: Step[];
33	}
34	
35	export type StepResult =
36	  | { premium: number }
37	  | { payout: number; remainingCap: number };
38	
39	export interface ScenarioResult {
40	  results: StepResult[];
41	}
42	
43	const PROCESSING_FEE = 5;
44	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
45	const BASE_PREMIUM_RATES: Record<string, number> = {
46	  sword: 100,
47	  amulet: 60,
48	  staff: 80,
49	  potion: 40,
50	  rune: 25,
51	  moonstone: 25,
52	};
53	
54	const CURSE_SURCHARGE_RATE = 0.5;
55	const HIGH_ENCHANTMENT_THRESHOLD = 5;
56	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
57	const LOYALTY_YEARS_THRESHOLD = 2;
58	const LOYALTY_DISCOUNT_RATE = 0.2;
59	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
60	const COMPONENT_BLOCK_SIZE = 3;
61	const COMPONENT_BLOCK_PREMIUM = 60;
62	
63	const INSURANCE_VALUES: Record<string, number> = {
64	  sword: 1000,
65	  amulet: 600,
66	  staff: 800,
67	  potion: 400,
68	  rune: 250,
69	  moonstone: 250,
70	};
71	
72	const DEDUCTIBLE_PER_DAMAGE = 100;
73	const CAP_MULTIPLIER = 2;
74	
75	const countByType = (items: Item[]): Map<string, number> =>
76	  items.reduce(
77	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
78	    new Map<string, number>(),
79	  );
80	
81	const basePremiumForGroup = (type: string, itemCount: number): number =>
82	  itemCount === COMPONENT_BLOCK_SIZE
83	    ? COMPONENT_BLOCK_PREMIUM
84	    : itemCount * BASE_PREMIUM_RATES[type];
85	
86	// The policy base premium: the sum of all item base premiums, EXCLUDING
87	// item-specific surcharges. Policy-wide modifiers are percentages of this.
88	const policyBasePremium = (items: Item[]): number =>
89	  [...countByType(items)].reduce(
90	    (sum, [type, itemCount]) => sum + basePremiumForGroup(type, itemCount),
91	    0,
92	  );
93	
94	const itemSurchargeRate = (item: Item): number =>
95	  (item.cursed ? CURSE_SURCHARGE_RATE : 0) +
96	  ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD
97	    ? HIGH_ENCHANTMENT_SURCHARGE_RATE
98	    : 0);
99	
100	const sumItemSurcharges = (items: Item[]): number =>
101	  items.reduce(
102	    (sum, item) => sum + BASE_PREMIUM_RATES[item.type] * itemSurchargeRate(item),
103	    0,
104	  );
105	
106	// Premiums round in the MHPCO's favor, i.e. up.
107	const roundPremiumInMHPCOsFavor = (premium: number): number =>
108	  Math.ceil(premium);
109	
110	// What the office knows about the customer at the moment a quote is drawn up.
111	// Policy-wide modifiers are decided entirely by this context.
112	interface QuoteContext {
113	  customer: Customer;
114	  precedingQuoteCount: number;
115	}
116	
117	// Each policy-wide modifier is a signed percentage of the policy base premium:
118	// surcharges positive, discounts negative.
119	const policyWideModifierRates = ({
120	  customer,
121	  precedingQuoteCount,
122	}: QuoteContext): number[] => [
123	  FIRST_INSURANCE_SURCHARGE_RATE,
124	  ...(customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD
125	    ? [-LOYALTY_DISCOUNT_RATE]
126	    : []),
127	  ...(precedingQuoteCount > 0 ? [-FOLLOW_UP_CONTRACT_DISCOUNT_RATE] : []),
128	];
129	
130	// Each rate is multiplied out against the base premium SEPARATELY and then
131	// summed. Summing the rates first and doing a single multiply is algebraically
132	// equal but not equal in floating point — 100 * (1 + 0.1) is 110.00000000000001
133	// — and rounding up turns that into a spurious extra gold piece.
134	const sumPolicyWideModifiers = (
135	  basePremium: number,
136	  context: QuoteContext,
137	): number =>
138	  policyWideModifierRates(context).reduce(
139	    (sum, rate) => sum + basePremium * rate,
140	    0,
141	  );
142	
143	const quote = (items: Item[], context: QuoteContext): StepResult => {
144	  const basePremium = policyBasePremium(items);
145	
146	  return {
147	    premium: roundPremiumInMHPCOsFavor(
148	      basePremium +
149	        sumItemSurcharges(items) +
150	        sumPolicyWideModifiers(basePremium, context) +
151	        PROCESSING_FEE,
152	    ),
153	  };
154	};
155	
156	const policyInsuranceSum = (items: Item[]): number =>
157	  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
158	
159	const claim = (step: ClaimStep, policyItems: Item[]): StepResult => {
160	  const payout = step.incident.damages.reduce(
161	    (sum, damage) => sum + damage.amount - DEDUCTIBLE_PER_DAMAGE,
162	    0,
163	  );
164	  const cap = policyInsuranceSum(policyItems) * CAP_MULTIPLIER;
165	
166	  return { payout, remainingCap: cap - payout };
167	};
168	
169	export const runScenario = (scenario: Scenario): ScenarioResult => {
170	  let precedingQuoteCount = 0;
171	  const policyItems: Item[][] = [];
172	
173	  const results = scenario.steps.map((step, stepIndex) => {
174	    if (step.op === "claim") {
175	      return claim(step, policyItems[step.policy]);
176	    }
177	
178	    const result = quote(step.items, {
179	      customer: scenario.customer,
180	      precedingQuoteCount,
181	    });
182	    policyItems[stepIndex] = step.items;
183	    precedingQuoteCount += 1;
184	
185	    return result;
186	  });
187	
188	  return { results };
189	};
